					}
					fmt.Fprint(w, `]`)
				case r.Method == http.MethodGet && strings.Contains(r.URL.Path, "/volumes/"):
					id := strings.TrimPrefix(r.URL.Path, "/20160918/volumes/")
					compartment := strings.TrimPrefix(id, "volume-")
