func New(factory *ociclient.Factory) (*Reader, error) {
	if factory == nil {
		return nil, errors.New("infrastructure inventory requires authenticated OCI factory")
	}
	return &Reader{factory: factory, pricesEndpoint: priceCatalog, http: &http.Client{Timeout: 15 * time.Second, CheckRedirect: func(*http.Request, []*http.Request) error { return errors.New("OCI price catalog redirect refused") }}}, nil
}

// Read prices directly enumerated compute and disks. Historical charges and
// exhaustive mutation coverage remain mandatory before authorizing growth.
func (r *Reader) Read(ctx context.Context, scope Scope) (Snapshot, error) {
	if err := scope.validate(time.Now()); err != nil {
		return Snapshot{}, err
	}
	result, err := r.ReadOwned(ctx, scope)
	if err != nil {
		return Snapshot{}, err
	}
	result.ExpiresAt = minTime(result.ExpiresAt, scope.ExpiresAt)
	result.seal = result.digest()
	return result, nil
}

// ReadOwned observes historical ownership without renewing expired spend authority.
func (r *Reader) ReadOwned(ctx context.Context, scope Scope) (Snapshot, error) {
	ctx, cancel := context.WithTimeout(ctx, 90*time.Second)
	defer cancel()
	started := time.Now()
	if err := scope.validateIdentity(); err != nil {
		return Snapshot{}, err
	}
	tenancy, err := r.factory.Provider().TenancyOCID()
	if err != nil || tenancy != scope.TenancyID {
		return Snapshot{}, errors.New("inventory principal differs from signed tenancy")
	}
	result := Snapshot{ScopeSHA256: scope.SHA256, Currency: scope.Currency, ObservedAt: started, ExpiresAt: started.Add(2 * time.Minute),
		Pending: []string{"current-month scope inception and exhaustive mutation history are not authenticated", "non-node charges and usage commitments require bounded accounting"}}
	prices := catalogReader{client: r.http, endpoint: r.pricesEndpoint, currency: scope.Currency, cache: map[string]tariff{}}
	seen := map[string]bool{}
	for _, region := range scope.Regions {
		factory, err := r.factory.ForRegion(region.OCIRegion)
		if err != nil {
			result.Pending = append(result.Pending, region.Cell+": "+err.Error())
			continue
		}
		search, err := factory.Search()
		if err != nil {
			result.Pending = append(result.Pending, region.Cell+": "+err.Error())
			continue
		}
		compute, err := factory.Compute()
		if err != nil {
			result.Pending = append(result.Pending, region.Cell+": "+err.Error())
			continue
		}
		block, err := factory.Blockstorage()
		if err != nil {
			result.Pending = append(result.Pending, region.Cell+": "+err.Error())
			continue
		}
		ociclient.PinHost(&search.BaseClient, r.endpoint)
		ociclient.PinHost(&compute.BaseClient, r.endpoint)
		ociclient.PinHost(&block.BaseClient, r.endpoint)
		for _, compartment := range region.CompartmentIDs {
			if strings.ContainsAny(compartment, "'\n\r") {
				return Snapshot{}, errors.New("invalid signed compartment identifier")
			}
			direct, directErr := directResources(ctx, compute, block, compartment)
			if directErr != nil {
				result.Pending = append(result.Pending, "direct family inventory incomplete: "+region.Cell+"/"+compartment+": "+directErr.Error())
			}
			observe := func(item resourcesearch.ResourceSummary) error {
				if item.Identifier == nil || *item.Identifier == "" || item.CompartmentId == nil || *item.CompartmentId != compartment || seen[*item.Identifier] {
					result.Pending = append(result.Pending, "duplicate, absent or out-of-scope OCI resource")
					return nil
				}
				seen[*item.Identifier] = true
				resource := Resource{ID: *item.Identifier, Cell: region.Cell, CompartmentID: compartment}
				amount, err := observedCost(ctx, compute, block, item, &prices, &resource)
				resource.MonthlyCents = amount
				if err != nil {
					result.Pending = append(result.Pending, resource.ID+": "+err.Error())
				}
				if math.MaxUint64-result.MonthlyCents < resource.MonthlyCents {
					return errors.New("infrastructure cost overflow")
				}
				result.MonthlyCents += resource.MonthlyCents
				result.Resources = append(result.Resources, resource)
				return nil
			}
			for _, item := range direct {
				if err := observe(item); err != nil {
					return Snapshot{}, err
				}
			}
			var page *string
			complete := false
			for range 64 {
				query := "query all resources where compartmentId = '" + compartment + "'"
				response, err := search.SearchResources(ociclient.RequestContext(ctx), resourcesearch.SearchResourcesRequest{SearchDetails: resourcesearch.StructuredSearchDetails{Query: new(query)}, Page: page})
				if err != nil {
					result.Pending = append(result.Pending, region.Cell+"/"+compartment+": "+err.Error())
					break
				}
				for _, item := range response.Items {
					if item.ResourceType != nil && (*item.ResourceType == "Instance" || *item.ResourceType == "Volume" || *item.ResourceType == "BootVolume") && item.Identifier != nil && seen[*item.Identifier] {
						continue
					}
					if err := observe(item); err != nil {
						return Snapshot{}, err
					}
				}
				page = response.OpcNextPage
				if page == nil || *page == "" {
					complete = true
					break
				}
			}
			if complete && directErr == nil {
				result.CoveredCompartments = append(result.CoveredCompartments, region.Cell+"/"+compartment)
			} else {
				result.Pending = append(result.Pending, "regional inventory pagination incomplete: "+region.Cell+"/"+compartment)
			}
		}
	}
	slices.SortFunc(result.Resources, func(a, b Resource) int { return strings.Compare(a.ID, b.ID) })
	slices.Sort(result.CoveredCompartments)
	slices.Sort(result.Pending)
	result.seal = result.digest()
	return result, nil
}

func observedCost(ctx context.Context, compute core.ComputeClient, block core.BlockstorageClient, item resourcesearch.ResourceSummary, prices *catalogReader, resource *Resource) (uint64, error) {
	if item.ResourceType == nil {
		return 0, errors.New("resource type missing")
	}
	var amount float64
	var evidenceErr error
	switch *item.ResourceType {
	case "Instance":
		response, err := compute.GetInstance(ociclient.RequestContext(ctx), core.GetInstanceRequest{InstanceId: item.Identifier})
		if err != nil {
			return 0, err
		}
		if response.Id == nil || *response.Id != *item.Identifier || response.CompartmentId == nil || *response.CompartmentId != *item.CompartmentId {
			return 0, errors.New("instance dimensions or identity missing")
		}
		resource.LifecycleState = string(response.LifecycleState)
		resource.OperationID = response.FreeformTags["ts-operation-id"]
		resource.RecipeSHA256 = response.FreeformTags["ts-recipe-sha256"]
		if terminalState(resource.LifecycleState) {
			return 0, nil
		}
		if response.Shape == nil || response.ShapeConfig == nil || response.ShapeConfig.Ocpus == nil || response.ShapeConfig.MemoryInGBs == nil || resource.LifecycleState == "" {
			return 0, errors.New("instance dimensions or lifecycle state missing")
		}
		resource.Shape, resource.OCPUs, resource.MemoryGB = *response.Shape, float64(*response.ShapeConfig.Ocpus), float64(*response.ShapeConfig.MemoryInGBs)
		if prices == nil {
			return 0, nil
		}
		cpuSKU, memorySKU, known := ocicost.ComputeSKUs(*response.Shape)
		if !known {
			return 0, fmt.Errorf("unknown shape tariff: %s", *response.Shape)
		}
		cpu, err := prices.price(ctx, cpuSKU, "OCPU Per Hour")
		if err != nil {
			return 0, err
		}
		memory, err := prices.price(ctx, memorySKU, "Gigabyte Per Hour")
		if err != nil {
			return 0, err
		}
		if !(*response.ShapeConfig.Ocpus > 0 && *response.ShapeConfig.MemoryInGBs > 0) {
			return 0, errors.New("invalid instance dimensions")
		}
		amount = 744 * (float64(*response.ShapeConfig.Ocpus)*cpu + float64(*response.ShapeConfig.MemoryInGBs)*memory)
	case "BootVolume", "Volume":
		var size, vpus *int64
		if *item.ResourceType == "BootVolume" {
			response, err := block.GetBootVolume(ociclient.RequestContext(ctx), core.GetBootVolumeRequest{BootVolumeId: item.Identifier})
			if err != nil {
				return 0, err
			}
			if response.Id == nil || *response.Id != *item.Identifier || response.CompartmentId == nil || *response.CompartmentId != *item.CompartmentId {
				return 0, errors.New("boot volume identity changed")
			}
			resource.LifecycleState = string(response.LifecycleState)
			resource.OperationID = response.FreeformTags["ts-operation-id"]
			resource.RecipeSHA256 = response.FreeformTags["ts-recipe-sha256"]
			if terminalState(resource.LifecycleState) {
				return 0, nil
			}
			if response.IsAutoTuneEnabled != nil && *response.IsAutoTuneEnabled || len(response.AutotunePolicies) > 0 {
				return 0, errors.New("autotuned disk requires a bounded performance charge ledger")
			}
			if prices != nil {
				evidenceErr = bootAttribution(ctx, compute, response.BootVolume, resource)
			}
			size, vpus = response.SizeInGBs, response.VpusPerGB
		} else {
			response, err := block.GetVolume(ociclient.RequestContext(ctx), core.GetVolumeRequest{VolumeId: item.Identifier})
			if err != nil {
				return 0, err
			}
			if response.Id == nil || *response.Id != *item.Identifier || response.CompartmentId == nil || *response.CompartmentId != *item.CompartmentId {
				return 0, errors.New("volume identity changed")
			}
			resource.LifecycleState = string(response.LifecycleState)
			resource.OperationID = response.FreeformTags["ts-operation-id"]
			resource.RecipeSHA256 = response.FreeformTags["ts-recipe-sha256"]
			if terminalState(resource.LifecycleState) {
				return 0, nil
			}
			if response.IsAutoTuneEnabled != nil && *response.IsAutoTuneEnabled || len(response.AutotunePolicies) > 0 {
				return 0, errors.New("autotuned disk requires a bounded performance charge ledger")
			}
			size, vpus = response.SizeInGBs, response.VpusPerGB
		}
		if size == nil || vpus == nil || *size <= 0 || *vpus < 0 || resource.LifecycleState == "" {
			return 0, errors.New("retained disk size or performance missing")
		}
		resource.SizeGB, resource.VPUs = float64(*size), *vpus
		if prices == nil {
			return 0, nil
		}
		storage, err := prices.price(ctx, "B91961", "Gigabyte Storage Capacity Per Month")
		if err != nil {
			return 0, err
		}
		performance, err := prices.price(ctx, "B91962", "Performance Units Per Gigabyte Per Month")
		if err != nil {
			return 0, err
		}
		amount = float64(*size) * (storage + float64(*vpus)*performance)
	default:
		return 0, fmt.Errorf("non-node resource %s has no complete current charge observation", *item.ResourceType)
	}
	if math.IsNaN(amount) || math.IsInf(amount, 0) || amount < 0 || amount > 1e12 {
		return 0, errors.New("resource cost outside bounds")
	}
	return uint64(math.Ceil(amount * 100)), evidenceErr
}

func directResources(ctx context.Context, compute core.ComputeClient, block core.BlockstorageClient, compartment string) ([]resourcesearch.ResourceSummary, error) {
	var resources []resourcesearch.ResourceSummary
	instances, instanceErr := inventoryPages(func(page *string) ([]core.Instance, *string, error) {
		response, err := compute.ListInstances(ociclient.RequestContext(ctx), core.ListInstancesRequest{CompartmentId: new(compartment), Page: page})
		return response.Items, response.OpcNextPage, err
	})
	for _, instance := range instances {
		resources = append(resources, resourcesearch.ResourceSummary{Identifier: instance.Id, CompartmentId: instance.CompartmentId, ResourceType: new("Instance"), LifecycleState: new(string(instance.LifecycleState))})
	}
	volumes, volumeErr := inventoryPages(func(page *string) ([]core.Volume, *string, error) {
		response, err := block.ListVolumes(ociclient.RequestContext(ctx), core.ListVolumesRequest{CompartmentId: new(compartment), Page: page})
		return response.Items, response.OpcNextPage, err
	})
	for _, volume := range volumes {
		resources = append(resources, resourcesearch.ResourceSummary{Identifier: volume.Id, CompartmentId: volume.CompartmentId, ResourceType: new("Volume"), LifecycleState: new(string(volume.LifecycleState))})
	}
	boots, bootErr := inventoryPages(func(page *string) ([]core.BootVolume, *string, error) {
		response, err := block.ListBootVolumes(ociclient.RequestContext(ctx), core.ListBootVolumesRequest{CompartmentId: new(compartment), Page: page})
		return response.Items, response.OpcNextPage, err
	})
	for _, boot := range boots {
		resources = append(resources, resourcesearch.ResourceSummary{Identifier: boot.Id, CompartmentId: boot.CompartmentId, ResourceType: new("BootVolume"), LifecycleState: new(string(boot.LifecycleState))})
	}
	return resources, errors.Join(instanceErr, volumeErr, bootErr)
}

func inventoryPages[T any](read func(*string) ([]T, *string, error)) ([]T, error) {
	var result []T
	var page *string
	seen := map[string]bool{}
	for range 64 {
		items, next, err := read(page)
		if err != nil {
			return result, err
		}
		result = append(result, items...)
		if len(result) > 10000 {
			return result, errors.New("direct OCI inventory exceeds resource bound")
		}
		if next == nil || *next == "" {
			return result, nil
		}
		if seen[*next] {
			return result, errors.New("direct OCI inventory repeated a pagination token")
		}
		seen[*next] = true
		page = next
	}
	return result, errors.New("direct OCI inventory pagination incomplete")
}

func bootAttribution(ctx context.Context, compute core.ComputeClient, boot core.BootVolume, resource *Resource) error {
	if resource.OperationID != "" && resource.RecipeSHA256 != "" {
		return nil
	}
	if boot.AvailabilityDomain == nil || *boot.AvailabilityDomain == "" || boot.Id == nil || boot.CompartmentId == nil {
		return errors.New("boot attribution requires exact compartment and AD readback")
	}
	attachments, err := inventoryPages(func(page *string) ([]core.BootVolumeAttachment, *string, error) {
		response, err := compute.ListBootVolumeAttachments(ociclient.RequestContext(ctx), core.ListBootVolumeAttachmentsRequest{CompartmentId: boot.CompartmentId, AvailabilityDomain: boot.AvailabilityDomain, BootVolumeId: boot.Id, Page: page})
		return response.Items, response.OpcNextPage, err
	})
	if err != nil {
		return fmt.Errorf("read boot attachment ancestry: %w", err)
	}
	instanceID := ""
	for _, attachment := range attachments {
		if attachment.BootVolumeId == nil || *attachment.BootVolumeId != *boot.Id || attachment.CompartmentId == nil || *attachment.CompartmentId != *boot.CompartmentId || attachment.AvailabilityDomain == nil || *attachment.AvailabilityDomain != *boot.AvailabilityDomain {
			return errors.New("boot attachment ancestry differs from direct volume scope")
		}
		if attachment.LifecycleState != core.BootVolumeAttachmentLifecycleStateAttached {
			continue
		}
		if attachment.InstanceId == nil || *attachment.InstanceId == "" || instanceID != "" && instanceID != *attachment.InstanceId {
			return errors.New("boot attachment ancestry is absent or ambiguous")
		}
		instanceID = *attachment.InstanceId
	}
	if instanceID == "" {
		return errors.New("boot operation membership requires a retained immutable journal binding")
	}
	response, err := compute.GetInstance(ociclient.RequestContext(ctx), core.GetInstanceRequest{InstanceId: new(instanceID)})
	if err != nil {
		return err
	}
	if response.Id == nil || *response.Id != instanceID || response.CompartmentId == nil || *response.CompartmentId != *boot.CompartmentId || response.AvailabilityDomain == nil || *response.AvailabilityDomain != *boot.AvailabilityDomain {
		return errors.New("boot ancestor differs from actual instance scope")
	}
	operation, recipe := response.FreeformTags["ts-operation-id"], response.FreeformTags["ts-recipe-sha256"]
	if operation == "" || recipe == "" || resource.OperationID != "" && resource.OperationID != operation || resource.RecipeSHA256 != "" && resource.RecipeSHA256 != recipe {
		return errors.New("boot ancestry lacks unambiguous operation and recipe attribution")
	}
	resource.OperationID, resource.RecipeSHA256 = operation, recipe
	return nil
}

func (c *catalogReader) price(ctx context.Context, sku, metric string) (float64, error) {
	if price, ok := c.cache[sku]; ok {
		if price.metric != metric {
			return 0, errors.New("OCI tariff unit mismatch")
		}
		return price.value, nil
	}
	endpoint, err := url.Parse(c.endpoint)
	if err != nil {
		return 0, err
	}
	query := endpoint.Query()
	query.Set("partNumber", sku)
	endpoint.RawQuery = query.Encode()
	request, err := http.NewRequestWithContext(ctx, http.MethodGet, endpoint.String(), nil)
	if err != nil {
		return 0, err
	}
	request.Header.Set("Cache-Control", "no-cache")
	response, err := c.client.Do(request)
	if err != nil {
		return 0, err
	}
	defer response.Body.Close()
	if response.StatusCode != http.StatusOK {
		return 0, fmt.Errorf("OCI price catalog HTTP %d", response.StatusCode)
	}
	servedAt, err := http.ParseTime(response.Header.Get("Date"))
	if err != nil || servedAt.After(time.Now().Add(time.Minute)) || time.Since(servedAt) > 2*time.Minute {
		return 0, errors.New("OCI tariff response freshness is absent or stale")
	}
	wire, err := io.ReadAll(io.LimitReader(response.Body, 1<<20+1))
	if err != nil || len(wire) > 1<<20 {
		return 0, errors.New("OCI price catalog unreadable or oversized")
	}
	var document struct {
		LastUpdated time.Time `json:"lastUpdated"`
		Items       []struct {
			PartNumber string `json:"partNumber"`
			Metric     string `json:"metricName"`
			Currencies []struct {
				Currency string `json:"currencyCode"`
				Prices   []struct {
					Model string   `json:"model"`
					Value *float64 `json:"value"`
				} `json:"prices"`
			} `json:"currencyCodeLocalizations"`
		} `json:"items"`
	}
	if err := json.Unmarshal(wire, &document); err != nil {
		return 0, err
	}
	if document.LastUpdated.IsZero() || document.LastUpdated.After(time.Now().Add(time.Minute)) || len(document.Items) != 1 || document.Items[0].PartNumber != sku || document.Items[0].Metric != metric {
		return 0, errors.New("OCI catalog lacks exact SKU, unit or publication date")
	}
	found, amount := false, 0.0
	for _, currency := range document.Items[0].Currencies {
		if currency.Currency != c.currency {
			continue
		}
		if found {
			return 0, errors.New("OCI catalog repeats currency")
		}
		for _, tier := range currency.Prices {
			if tier.Model != "PAY_AS_YOU_GO" {
				continue
			}
			if tier.Value == nil || math.IsNaN(*tier.Value) || math.IsInf(*tier.Value, 0) || *tier.Value < 0 || *tier.Value > 1e7 {
				return 0, errors.New("OCI tariff invalid")
			}
			// Price at the highest published tier; free allowances are not spending authority.
			amount, found = max(amount, *tier.Value), true
		}
	}
	if !found {
		return 0, errors.New("OCI catalog has no payable tariff in authorized currency")
	}
	c.cache[sku] = tariff{amount, metric}
	return amount, nil
}

// Prices reads current tariffs for observed compatible shapes. Shapes without
// reviewed SKU identities stay unpriced; known candidates can still be compared.
func (r *Reader) Prices(ctx context.Context, scope Scope, shapes []string) ([]ocicost.Price, error) {
	ctx, cancel := context.WithTimeout(ctx, 45*time.Second)
	defer cancel()
	if err := scope.validate(time.Now()); err != nil {
		return nil, err
	}
	if len(shapes) > 256 {
		return nil, errors.New("OCI candidate shape set exceeds inventory bound")
	}
	units := map[string]string{"B91961": "Gigabyte Storage Capacity Per Month", "B91962": "Performance Units Per Gigabyte Per Month"}
	knownShape := false
	for _, shape := range shapes {
		cpu, memory, known := ocicost.ComputeSKUs(shape)
		if !known {
			continue
		}
		knownShape = true
		units[cpu], units[memory] = "OCPU Per Hour", "Gigabyte Per Hour"
	}
	if !knownShape {
		return nil, errors.New("observed OCI shapes have no reviewed tariff identities")
	}
	catalog := catalogReader{client: r.http, endpoint: r.pricesEndpoint, currency: scope.Currency, cache: map[string]tariff{}}
	var prices []ocicost.Price
	var failures []error
	for _, sku := range slices.Sorted(maps.Keys(units)) {
		value, err := catalog.price(ctx, sku, units[sku])
		if err != nil {
			failures = append(failures, fmt.Errorf("SKU %s: %w", sku, err))
			continue
		}
		prices = append(prices, ocicost.Price{SKU: sku, PerUnit: value})
	}
	return prices, errors.Join(failures...)
}

	prices                                          []ocicost.Price
}

func (q Quote) Prices() []ocicost.Price { return slices.Clone(q.prices) }
func (q Quote) Currency() string        { return q.currency }
func (q Quote) MonthlyCents() uint64    { return q.monthlyCents }
func (q Quote) IssuedAt() time.Time     { return q.issuedAt }
func (q Quote) ExpiresAt() time.Time    { return q.expiresAt }

// Original retains the exact quote for a protected financial receipt. The
// returned data does not carry the SDK producer's spending authority.
func (q Quote) Original() capacityledger.Quote {
	return capacityledger.Quote{ScopeSHA256: q.scopeSHA256, Cell: q.cell, CompartmentID: q.compartment,
		Shape: q.shape, Currency: q.currency, OCPUs: q.ocpus, MemoryGB: q.memoryGB, BootGB: q.bootGB,
		MonthlyCents: q.monthlyCents, IssuedAt: q.issuedAt, ExpiresAt: q.expiresAt, Prices: slices.Clone(q.prices)}
}

func (q Quote) Validate(scope Scope, cell, compartment, shape string, ocpus, memoryGB, bootGB float64, now time.Time) error {
	if err := scope.validate(now); err != nil {
		return err
	}
	if q.scopeSHA256 != scope.SHA256 || q.currency != scope.Currency || q.cell != cell || q.compartment != compartment || q.shape != shape || q.ocpus != ocpus || q.memoryGB != memoryGB || q.bootGB != bootGB || len(q.prices) != 4 || q.issuedAt.After(now) || now.Sub(q.issuedAt) > 2*time.Minute || !now.Before(q.expiresAt) || q.expiresAt.After(scope.ExpiresAt) {
		return errors.New("current tariff quote is absent, stale or differs from exact authorized geometry")
	}
	return nil
}

func (r *Reader) Quote(ctx context.Context, scope Scope, cell, compartment, shape string, ocpus, memoryGB, bootGB float64) (Quote, error) {
	ctx, cancel := context.WithTimeout(ctx, 45*time.Second)
	defer cancel()
	now := time.Now()
	if err := scope.validate(now); err != nil {
		return Quote{}, err
	}
	owned := false
	for _, region := range scope.Regions {
		owned = owned || region.Cell == cell && slices.Contains(region.CompartmentIDs, compartment)
	}
	if !owned {
		return Quote{}, errors.New("candidate quote lies outside authorized regional footprint")
	}
	prices, err := r.Prices(ctx, scope, []string{shape})
	if err != nil {
		return Quote{}, err
	}
	monthly, known := ocicost.NodeMonthlyCents(prices, shape, ocpus, memoryGB, bootGB)
	if !known {
		return Quote{}, errors.New("candidate quote has invalid billing dimensions or tariffs")
	}
	return Quote{scopeSHA256: scope.SHA256, cell: cell, compartment: compartment, shape: shape, currency: scope.Currency, ocpus: ocpus, memoryGB: memoryGB, bootGB: bootGB, monthlyCents: monthly, issuedAt: now, expiresAt: minTime(now.Add(2*time.Minute), scope.ExpiresAt), prices: prices}, nil
}

func (s Snapshot) digest() [32]byte {
	wire, _ := json.Marshal(s, json.Deterministic(true))
	return sha256.Sum256(wire)
}

func (s Snapshot) Validate(scope Scope, now time.Time) error {
	if err := s.ValidateOwned(scope, now); err != nil {
		return err
	}
	if !now.Before(scope.ExpiresAt) || s.ExpiresAt.After(scope.ExpiresAt) {
		return errors.New("infrastructure spend authority expired")
	}
	return nil
}

// ValidateOwned permits read-only reconciliation after historical authority expires.
func (s Snapshot) ValidateOwned(scope Scope, now time.Time) error {
	if s.seal == ([32]byte{}) || s.seal != s.digest() {
		return errors.New("infrastructure snapshot lacks intact SDK producer evidence")
	}
	if s.ScopeSHA256 != scope.SHA256 || s.Currency != scope.Currency || len(s.Pending) != 0 {
		return errors.New("infrastructure snapshot is incomplete or outside signed scope")
	}
	if s.ObservedAt.After(now) || now.Sub(s.ObservedAt) > 2*time.Minute || !now.Before(s.ExpiresAt) {
		return errors.New("infrastructure snapshot is stale or outside authority validity")
	}
	want := []string{}
	for _, region := range scope.Regions {
		for _, compartment := range region.CompartmentIDs {
			want = append(want, region.Cell+"/"+compartment)
		}
	}
	slices.Sort(want)
	got := slices.Clone(s.CoveredCompartments)
	slices.Sort(got)
	if len(want) == 0 || !slices.Equal(want, got) {
		return errors.New("infrastructure snapshot does not cover every authorized compartment")
	}
	return nil
}

func (s Scope) validate(now time.Time) error {
	if !now.Before(s.ExpiresAt) {
		return errors.New("infrastructure spend authority expired")
	}
	return s.validateIdentity()
}

func (s Scope) validateIdentity() error {
	digest, err := hex.DecodeString(s.SHA256)
	if err != nil || len(digest) != 32 || s.TenancyID == "" || (s.Currency != "USD" && s.Currency != "BRL") || len(s.Regions) == 0 {
		return errors.New("verified infrastructure scope is absent, expired or incomplete")
	}
	seen := map[string]bool{}
	for _, region := range s.Regions {
		if region.Cell == "" || region.OCIRegion == "" || len(region.CompartmentIDs) == 0 {
			return errors.New("infrastructure scope lacks a regional compartment")
		}
		for _, compartment := range region.CompartmentIDs {
			key := region.Cell + "/" + compartment
			if compartment == "" || seen[key] {
				return fmt.Errorf("infrastructure scope repeats or omits a compartment: %s", key)
			}
			seen[key] = true
		}
	}
	return nil
}

func New(provider common.ConfigurationProvider, options Options) (*Factory, error) {
	if provider == nil {
		return nil, errors.New("OCI client factory requires a configuration provider")
	}
	if !catalog.IsOCIRegion(options.Region) {
		return nil, fmt.Errorf("OCI client factory region %q is not in the region catalog", options.Region)
	}
	limits := make(map[Service]Limit, len(DefaultLimits))
	for service, limit := range DefaultLimits {
		limits[service] = limit
	}
	for service, limit := range options.Limits {
		if limit.PerSecond <= 0 || limit.Burst < 1 {
			return nil, fmt.Errorf("OCI client limit for %s must be positive", service)
		}
		limits[service] = limit
	}
	return &Factory{provider: provider, region: options.Region, limits: limits,
		policy: RetryPolicy(options.Retry), limiters: map[Service]*rate.Limiter{}}, nil

// Limiter returns the shared token bucket for service.
func (f *Factory) Limiter(service Service) *rate.Limiter {
	f.mu.Lock()
	defer f.mu.Unlock()
	if limiter := f.limiters[service]; limiter != nil {
		return limiter
	}
	limit, ok := f.limits[service]
	if !ok {
		limit = defaultLimit
	}
	limiter := rate.NewLimiter(rate.Limit(limit.PerSecond), limit.Burst)
	f.limiters[service] = limiter
	return limiter
}

// Configure installs the shared limiter and retry policy on an SDK client and
// pins it to the factory region. An existing interceptor still runs, after the
// limiter admits the request. Each retry attempt passes through the limiter.
func (f *Factory) Configure(client *common.BaseClient, service Service) {
	limiter := f.Limiter(service)
	previous := client.Interceptor
	client.Interceptor = func(request *http.Request) error {
		ctx := request.Context()
		if ctx == nil {
			ctx = context.Background()
		}
		if err := limiter.Wait(ctx); err != nil {
			return fmt.Errorf("OCI %s rate limiter: %w", service, err)
		}
		if request.Method != http.MethodGet && request.Method != http.MethodHead && request.Method != http.MethodOptions {
			if guard, ok := ctx.Value(authorityKey{}).(func(context.Context) error); ok {
				if err := guard(ctx); err != nil {
					return fmt.Errorf("OCI %s write authority: %w", service, err)
				}
			}
		}
		if previous != nil {
			return previous(request)
		}
		return nil
	}
	policy := f.policy
	// Set only the retry policy: replacing the whole configuration would drop
	// a circuit breaker the SDK installed from OCI_SDK_DEFAULT_CIRCUITBREAKER_ENABLED
	// or its global setting.
	client.Configuration.RetryPolicy = &policy
	ConfigureReadCancellation(client)
}

// PinHost replaces a client's endpoint with an exact canonical endpoint. It is
// used by callers whose signed configuration names the endpoint.
func PinHost(client *common.BaseClient, endpoint string) {
	if endpoint = strings.TrimSuffix(endpoint, "/"); endpoint != "" {
		client.Host = endpoint
	}
}

