func fileSHA(path string) string {
	wire := must(os.ReadFile(path))
	h := sha256.Sum256(wire)
	return hex.EncodeToString(h[:])
}
func wireSHA(wire []byte) string { h := sha256.Sum256(wire); return hex.EncodeToString(h[:]) }
func readBytes(path string, limit int, label string) []byte {
	fd, err := unix.Open(path, unix.O_RDONLY|unix.O_CLOEXEC|unix.O_NOFOLLOW, 0)
	if err != nil {
		fail(label + " is unreadable or invalid JSON")
	}
	f := os.NewFile(uintptr(fd), path)
	defer f.Close()
	st, err := f.Stat()
	if err != nil {
		fail(label + " is unreadable or invalid JSON")
	}
	if !st.Mode().IsRegular() || st.Size() <= 0 || st.Size() > int64(limit) {
		fail(label + " has invalid size or is not a regular file")
	}
	wire := must(io.ReadAll(io.LimitReader(f, int64(limit+1))))
	if len(wire) == 0 || len(wire) > limit {
		fail(label + " has invalid size")
	}
	return wire
}
func readJSON(path string, limit int, label string) Object {
	wire := readBytes(path, limit, label)
	v, err := decodeJSON(wire)
	if err != nil {
		if strings.Contains(err.Error(), "duplicate") {
			fail("JSON document has duplicate fields")
		}
		fail(label + " is unreadable or invalid JSON")
	}
	m, ok := v.(map[string]any)
	if !ok {
		fail(label + " must be an object")
	}
	return m
}

func enrollmentBundle(t *testing.T) []byte {
	t.Helper()
	caKey, err := ecdsa.GenerateKey(elliptic.P256(), rand.Reader)
	if err != nil {
		t.Fatal(err)
	}
	template := &x509.Certificate{SerialNumber: big.NewInt(1), Subject: pkix.Name{CommonName: "member launch CA"}, NotBefore: cellNow.Add(-time.Hour), NotAfter: time.Now().Add(time.Hour), IsCA: true, BasicConstraintsValid: true, KeyUsage: x509.KeyUsageCertSign}
	caDER, err := x509.CreateCertificate(rand.Reader, template, template, &caKey.PublicKey, caKey)
	if err != nil {
		t.Fatal(err)
	}
	responsePublic, _, err := ed25519.GenerateKey(rand.Reader)
	if err != nil {
		t.Fatal(err)
	}
	account, err := nkeys.CreateAccount()
	if err != nil {
		t.Fatal(err)
	}
	accountPublic, err := account.PublicKey()
	if err != nil {
		t.Fatal(err)
	}
	bundle := hostenroll.PublicBundle{SchemaVersion: 1, Cell: "gru", Region: "GRU",
		ControllerEndpoints: []string{"10.251.0.11:8443", "10.251.0.12:8443", "10.251.0.13:8443"},
		NATSURLs:            []string{"tls://10.251.0.11:4222", "tls://10.251.0.12:4222", "tls://10.251.0.13:4222"},
		CAPEM:               string(pem.EncodeToMemory(&pem.Block{Type: "CERTIFICATE", Bytes: caDER})), ControllerResponsePublicKey: base64.StdEncoding.EncodeToString(responsePublic),
		CellAccountNKey: accountPublic, Environment: "production", InstallRoot: hostenroll.ImageInstallRoot, StateRoot: hostenroll.ImageStateRoot,
		ManagedRuntimeRoot: hostenroll.ImageManagedRuntimeRoot, WorkloadUID: hostenroll.ImageWorkloadUID, WorkloadGID: hostenroll.ImageWorkloadGID}
	wire, err := json.Marshal(bundle)
	if err != nil {
		t.Fatal(err)
	}
	return wire
}

func ownerSSHKey(t *testing.T) []byte {
	t.Helper()
	public, _, err := ed25519.GenerateKey(rand.Reader)
	if err != nil {
		t.Fatal(err)
	}
	wire := binary.BigEndian.AppendUint32(nil, 11)
	wire = binary.BigEndian.AppendUint32(append(wire, "ssh-ed25519"...), 32)
	return []byte("ssh-ed25519 " + base64.StdEncoding.EncodeToString(append(wire, public...)) + " operator\n")
}

func ParsePublicBundle(wire []byte) (PublicBundle, error) {
	if len(wire) == 0 || len(wire) > MaxPublicBundleBytes {
		return PublicBundle{}, errors.New("host enrollment public bundle is missing or too large")
	}
	var bundle PublicBundle
	if err := json.Unmarshal(wire, &bundle, json.RejectUnknownMembers(true)); err != nil {
		return PublicBundle{}, fmt.Errorf("parse host enrollment public bundle: %w", err)
	}
	if err := bundle.Validate(); err != nil {
		return PublicBundle{}, err
	}
	return bundle, nil
}

func (bundle PublicBundle) Validate() error {
	if bundle.SchemaVersion != 1 || !validCellRegion(bundle.Cell, bundle.Region) ||
		bundle.Environment != "canary" && bundle.Environment != "production" ||
		bundle.WorkloadUID == 0 || bundle.WorkloadGID == 0 ||
		!cleanRoot(bundle.InstallRoot) || !cleanRoot(bundle.StateRoot) || !cleanRoot(bundle.ManagedRuntimeRoot) ||
		pathsOverlap(bundle.InstallRoot, bundle.StateRoot) || pathsOverlap(bundle.InstallRoot, bundle.ManagedRuntimeRoot) ||
		pathsOverlap(bundle.StateRoot, bundle.ManagedRuntimeRoot) {
		return errors.New("host enrollment public bundle has invalid identity or local paths")
	}
	if _, err := bundle.ResponsePublicKey(); err != nil {
		return err
	}
	if !nkeys.IsValidPublicAccountKey(bundle.CellAccountNKey) {
		return errors.New("host enrollment cell account key is invalid")
	}
	if _, err := bundle.RootCAs(); err != nil {
		return err
	}
	if len(bundle.ControllerEndpoints) != 3 || len(bundle.NATSURLs) != 3 {
		return errors.New("host enrollment needs exactly three regional controller and NATS endpoints")
	}
	controllers := make([]netip.Addr, 0, 3)
	natsPeers := make([]netip.Addr, 0, 3)
	for _, endpoint := range bundle.ControllerEndpoints {
		ip, err := parseEndpoint(endpoint, "8443")
		if err != nil || slices.Contains(controllers, ip) {
			return errors.New("host enrollment controller endpoints must be distinct private IPv4 port 8443 addresses")
		}
		controllers = append(controllers, ip)
	}
	for _, raw := range bundle.NATSURLs {
		parsed, err := url.Parse(raw)
		if err != nil || parsed.Scheme != "tls" || parsed.User != nil || parsed.RawQuery != "" || parsed.Fragment != "" || parsed.Path != "" {
			return errors.New("host enrollment NATS URLs must be direct private TLS endpoints")
		}
		ip, err := parseEndpoint(parsed.Host, "4222")
		if err != nil || slices.Contains(natsPeers, ip) {
			return errors.New("host enrollment NATS endpoints must be distinct private IPv4 port 4222 addresses")
		}
		natsPeers = append(natsPeers, ip)
	}
	slices.SortFunc(controllers, netip.Addr.Compare)
	slices.SortFunc(natsPeers, netip.Addr.Compare)
	if !slices.Equal(controllers, natsPeers) {
		return errors.New("host enrollment controller and NATS endpoints differ")
	}
	return nil

func Static(cell, region, node string) Descriptor {
	return Descriptor{SchemaVersion: StaticSchemaVersion, Cell: cell, Region: region, Node: node}
}

// IsStatic reports whether the descriptor names a static host.
func (descriptor Descriptor) IsStatic() bool { return descriptor.SchemaVersion == StaticSchemaVersion }

// IsController reports whether a static descriptor names a controller VM.
func (descriptor Descriptor) IsController() bool {
	cell, err := naming.RegionCell(descriptor.Region).Name()
	return descriptor.IsStatic() && err == nil && (strings.HasPrefix(descriptor.Node, cell+"-"+naming.Controller+"-") ||
		strings.HasPrefix(descriptor.Node, regionNode(descriptor.Region)))
}

// regionNode is the prefix of the region's node names, e.g. ts-sfo-.
func regionNode(region string) string { return "ts-" + strings.ToLower(region) + "-" }

// Validate checks the closed v1 identity and digest bindings and the bounded
// canonical wire size. It performs no signature or live-resource checks.
func (descriptor Descriptor) Validate() error {
	_, err := descriptor.CanonicalBytes()
	return err
}

// CanonicalBytes returns the deterministic v1 JSON representation used in OCI
// instance metadata and retry binding.
func (descriptor Descriptor) CanonicalBytes() ([]byte, error) {
	if err := descriptor.validateFields(); err != nil {
		return nil, err
	}
	wire, err := protocol.EncodeJSON(descriptor)
	if err != nil {
		return nil, fmt.Errorf("%w: encode canonical JSON: %v", ErrInvalidDescriptor, err)
	}
	if len(wire) == 0 || len(wire) > MaxDescriptorBytes {
		return nil, fmt.Errorf("%w: canonical JSON exceeds %d bytes", ErrInvalidDescriptor, MaxDescriptorBytes)
	}
	return wire, nil

func (descriptor Descriptor) validateFields() error {
	if descriptor.IsStatic() {
		cell, err := naming.RegionCell(descriptor.Region).Name()
		number, ok := strings.CutPrefix(descriptor.Node, cell+"-"+naming.Member+"-")
		if !ok {
			number, ok = strings.CutPrefix(descriptor.Node, cell+"-"+naming.Controller+"-")
		}
		if !ok {
			number, ok = strings.CutPrefix(descriptor.Node, regionNode(descriptor.Region))
		}
		if pool, isPool := strings.CutPrefix(descriptor.Node, cell+"-pool-"); !ok && isPool {
			// The scheme allows no hyphen in a pool name.
			_, number, ok = strings.Cut(pool, "-")
		}
		if err != nil || !validCellRegion(descriptor.Cell, descriptor.Region) || !ok ||
			naming.Validate(descriptor.Node) != nil || strings.Contains(number, "-") ||
			descriptor != Static(descriptor.Cell, descriptor.Region, descriptor.Node) {
			return fmt.Errorf("%w: static host must name one database, controller, node or pool server of its cell and nothing else", ErrInvalidDescriptor)
		}
		return nil
	}
	if descriptor.SchemaVersion != SchemaVersion || !validCellRegion(descriptor.Cell, descriptor.Region) ||
		!descriptorToken.MatchString(descriptor.Node) || !descriptorToken.MatchString(descriptor.Owner) ||
		!validCreateKey(descriptor.CreateKey) || !descriptorImageID.MatchString(descriptor.ImageID) ||
		descriptor.FleetGeneration == 0 || descriptor.HostAttempt == 0 || descriptor.IntentGeneration == 0 ||
		!entityid.Valid(descriptor.DatabaseID) || !entityid.Valid(descriptor.PartitionID) ||
		!entityid.Valid(descriptor.SeatID) ||
		!descriptorDigest.MatchString(descriptor.IntentPayloadDigest) ||
		!descriptorDigest.MatchString(descriptor.CanonicalRosterDigest) ||
		!descriptorDigest.MatchString(descriptor.ManagedHostProfileDigest) ||
		!descriptorDigest.MatchString(descriptor.RuntimeManifestDigest) {
		return fmt.Errorf("%w: required identity, generation, image, or digest binding", ErrInvalidDescriptor)
	}
	return nil
}

func validCellRegion(cell, region string) bool {
	return catalog.MatchesName(cell, region)
}

type fakeOCI struct {
	mu        sync.Mutex
	seq       int
	rows      map[string]*row
	order     []string
	nsgRules  map[string][]any
	retention map[string][]any
	writes    []string
	args      [][]string
	failOn    string
	// peer serves the private peering's actions; see peer_test.go.
	peer func(region string, c sdkcli.Command) (any, bool, error)
}

type row struct {
	kind, region string
	data         Object
}

// kinds are each resource's OCID kind, whether it is global (IAM) and the
// state it is created in.
var kinds = map[string]struct {
	ocid   string
	global bool
	state  string
}{
	"compartment": {"compartment", true, "ACTIVE"}, "dynamic-group": {"dynamicgroup", true, "ACTIVE"}, "policy": {"policy", true, "ACTIVE"},
	"vcn": {"vcn", false, "AVAILABLE"}, "service-gateway": {"servicegateway", false, "AVAILABLE"}, "route-table": {"routetable", false, "AVAILABLE"},
	"security-list": {"securitylist", false, "AVAILABLE"}, "subnet": {"subnet", false, "AVAILABLE"}, "nsg": {"networksecuritygroup", false, "AVAILABLE"},
	"vault": {"vault", false, "CREATING"}, "key": {"key", false, "CREATING"}, "bucket": {"bucket", false, ""},
	"drg": {"drg", false, "AVAILABLE"}, "remote-peering-connection": {"remotepeeringconnection", false, "AVAILABLE"},
	"drg-route-distribution": {"drgroutedistribution", false, "AVAILABLE"}, "drg-route-table": {"drgroutetable", false, "AVAILABLE"},
	"drg-attachment": {"drgattachment", false, "ATTACHED"},
}

func newFake() *fakeOCI {
	return &fakeOCI{rows: map[string]*row{}, nsgRules: map[string][]any{}, retention: map[string][]any{}}
}

type client struct {
	f      *fakeOCI
	region string
}

// Call prints a route table's or security list's ETag beside its data, as
// the oci CLI does.
func (c client) Call(_ context.Context, args ...string) (map[string]any, error) {
	v, err := c.f.handle(c.region, args)
	r := map[string]any{"data": v}
	if m, ok := v.(Object); ok && m["etag"] != nil {
		r["etag"] = m["etag"]
	}
	return r, err
}
func (c client) Head(context.Context, ...string) error { return errors.New("unexpected head") }

// dependency serves the inspection engine's oci reads; IAM reads name no
// region.
func (f *fakeOCI) dependency(name string, args []any, kwargs Object) (any, error) {
	if name != "oci" {
		return nil, fmt.Errorf("unexpected dependency %s", name)
	}
	words := make([]string, len(args))
	for i, a := range args {
		words[i] = fmt.Sprint(a)
	}
	region, _ := kwargs["region"].(string)
	if region == "" {
		region = home
	}
	v, err := f.handle(region, words)
	if err != nil {
		return nil, err
	}
	// The engine compares typed plan values with decoded responses.
	wire, _ := json.Marshal(v)
	return decode(wire), nil
}

func (f *fakeOCI) handle(region string, args []string) (any, error) {
	f.mu.Lock()
	defer f.mu.Unlock()
	c, err := sdkcli.Parse(args)
	if err != nil {
		return nil, err
	}
	words := strings.Fields(c.Path)
	verb, flags := words[len(words)-1], c.Flags
	if verb != "get" && verb != "list" {
		f.writes = append(f.writes, region+" "+c.Path)
		f.args = append(f.args, args)
		if c.Path == f.failOn {
			f.failOn = ""
			return nil, errors.New("connection reset")
		}
		if words[0] == "iam" && region != home {
			return nil, errors.New("403 NotAllowed: IAM writes are accepted only in the home region")
		}
	}
	if f.peer != nil {
		if v, ok, err := f.peer(region, c); ok {
			return v, err
		}
	}
	switch c.Path {
	case "os ns get":
		return "fakens", nil
	case "os bucket get":
		b, err := f.bucket(region, flags["bucket-name"])
		if err != nil {
			return nil, err
		}
		return clone(b.data), nil
	case "network nsg rules add":
		var rules []any
		if err := json.Unmarshal([]byte(flags["security-rules"]), &rules); err != nil {
			return nil, err
		}
		for _, r := range kebab(rules).([]any) {
			f.seq++
			r.(Object)["id"] = fmt.Sprintf("rule%d", f.seq)
			f.nsgRules[flags["nsg-id"]] = append(f.nsgRules[flags["nsg-id"]], r)
		}
		return Object{}, nil
	case "network nsg rules list":
		return clone(append([]any{}, f.nsgRules[flags["nsg-id"]]...)), nil
	case "network nsg rules remove":
		var ids []string
		if err := json.Unmarshal([]byte(flags["security-rule-ids"]), &ids); err != nil {
			return nil, err
		}
		f.nsgRules[flags["nsg-id"]] = slices.DeleteFunc(f.nsgRules[flags["nsg-id"]], func(r any) bool {
			return slices.Contains(ids, text(r.(Object)["id"]))
		})
		return Object{}, nil
	case "os retention-rule create":
		var amount int
		fmt.Sscan(flags["time-amount"], &amount)
		f.retention[flags["bucket-name"]] = append(f.retention[flags["bucket-name"]],
			Object{"display-name": flags["display-name"], "duration": Object{"time-amount": amount, "time-unit": flags["time-unit"]}})
		return Object{}, nil
	case "os retention-rule list":
		return clone(append([]any{}, f.retention[flags["bucket-name"]]...)), nil
	}
	kind := words[len(words)-2]
	switch verb {
	case "create":
		data := Object{}
		for name, value := range flags {
			switch {
			case name == "wait-for-state" || name == "endpoint" || name == "namespace-name":
			case value == "true" || value == "false":
				data[name] = value == "true"
			case strings.HasPrefix(value, "[") || strings.HasPrefix(value, "{"):
				data[name] = kebab(decode([]byte(value)))
			default:
				data[name] = value
			}
		}
		switch kind {
		case "subnet":
			data["prohibit-internet-ingress"] = data["prohibit-public-ip-on-vnic"]
		case "vault":
			f.seq++
			data["management-endpoint"] = fmt.Sprintf("https://v%d-management.kms.%s.oraclecloud.com", f.seq, region)
		case "key":
			vault := f.find("vault", region, func(o Object) bool { return o["management-endpoint"] == flags["endpoint"] })
			data["vault-id"] = vault[0].data["id"]
		case "bucket":
			if _, err := f.bucket(region, flags["name"]); err == nil {
				return nil, errors.New("409 BucketAlreadyExists")
			}
		case "route-table", "security-list":
			data["etag"] = "1"
		case "drg-route-distribution", "drg-route-table", "drg-attachment":
			data["compartment-id"] = f.rows[flags["drg-id"]].data["compartment-id"]
			if kind == "drg-route-table" {
				data["import-drg-route-distribution-id"] = data["import-route-distribution-id"]
				delete(data, "import-route-distribution-id")
			}
			if kind == "drg-attachment" {
				data["is-cross-tenancy"] = false
			}
		case "remote-peering-connection":
			data["peering-status"], data["is-cross-tenancy-peering"] = "NEW", false
		}
		id := f.add(kind, region, data)
		if kind == "remote-peering-connection" {
			// OCI attaches a new RPC to its DRG's default RPC route table.
			f.add("drg-attachment", region, Object{"compartment-id": data["compartment-id"], "drg-id": data["drg-id"],
				"network-details": Object{"type": "REMOTE_PEERING_CONNECTION", "id": id}, "is-cross-tenancy": false,
				"drg-route-table-id": "ocid1.drgroutetable.oc1." + region + ".default"})
		}
		return clone(f.rows[id].data), nil
	case "get":
		for name, id := range flags {
			if !strings.HasSuffix(name, "-id") && name != "rt-id" {
				continue
			}
			r := f.rows[id]
			if r == nil || r.kind != kind || (r.region != "" && r.region != region) {
				return nil, fmt.Errorf("404 NotAuthorizedOrNotFound: %s", id)
			}
			v := clone(r.data)
			// A vault and its key read back CREATING once, then ready.
			switch r.data["lifecycle-state"] {
			case "CREATING":
				r.data["lifecycle-state"] = map[string]string{"vault": "ACTIVE", "key": "ENABLED"}[kind]
			}
			return v, nil
		}
		return nil, fmt.Errorf("no id for %s", c.Path)
	case "list":
		var endpointVault any
		if endpoint := flags["endpoint"]; endpoint != "" {
			endpointVault = f.find("vault", region, func(o Object) bool { return o["management-endpoint"] == endpoint })[0].data["id"]
		}
		r := []any{}
		attachment := flags["attachment-type"]
		for _, x := range f.find(kind, region, func(o Object) bool {
			return (flags["compartment-id"] == "" || o["compartment-id"] == flags["compartment-id"]) && (flags["vcn-id"] == "" || o["vcn-id"] == flags["vcn-id"]) &&
				(endpointVault == nil || o["vault-id"] == endpointVault) && (flags["drg-id"] == "" || o["drg-id"] == flags["drg-id"]) &&
				(attachment == "" || attachment == "ALL" || obj(o["network-details"])["type"] == attachment)
		}) {
			r = append(r, clone(x.data))
		}
		return r, nil
	}
	return nil, fmt.Errorf("unexpected OCI command %s", c.Path)
}

func loadPlan(t *testing.T) Object {
	t.Helper()
	plan, err := ociregion.LoadPlan(filepath.Join("..", "..", "..", "deploy", "oci-region", "sfo-1-plan.json"))
	if err != nil {
		t.Fatal(err)
	}
	return plan
}

func allowWrite(ctx context.Context, _ bool) (context.Context, func(), error) {
	return ctx, func() {}, nil
}
func allowGuard(context.Context) error { return nil }

func run(t *testing.T, f *fakeOCI, apply bool, out string, plans ...Object) (string, error) {
	t.Helper()
	plan := loadPlan(t)
	if len(plans) != 0 {
		plan = plans[0]
	}
	var log bytes.Buffer
	foundation := &Foundation{Region: client{f, sfo}, Home: client{f, home}, Apply: apply, Out: &log,
		BeforeWrite: allowWrite, Guard: allowGuard, Checkpoint: func(context.Context, string, string) error { return nil },
		CheckpointAuxiliary: func(context.Context, string, string) error { return nil },
		Pause:               func(context.Context, time.Duration) error { return nil },
		Check:               (&ociregion.Engine{Context: t.Context(), Dependency: f.dependency}).CheckFoundation}
	err := foundation.Run(t.Context(), plan, out)
	return log.String(), err
}

// creates are the writes a first apply of sfo-1's plan makes, each once.
var creates = []string{
	"iam compartment create", "iam compartment create", "iam compartment create",
	"network vcn create", "network service-gateway create", "network route-table create", "network security-list create",
	"network subnet create", "network nsg create", "network nsg rules add", "network nsg create", "network nsg rules add",
	"kms management vault create", "kms management key create",
	"iam dynamic-group create", "iam dynamic-group create", "iam policy create", "iam policy create", "iam policy create", "iam policy create",
	"os bucket create", "os retention-rule create", "os bucket create", "os bucket create", "os retention-rule create", "os bucket create",
}

func (f *Foundation) Run(ctx context.Context, plan Object, out string) error {
	delete(plan, "_source_path")
	ids, err := f.bind(ctx, plan)
	if err != nil {
		return err
	}
	if !f.Apply {
		if f.planned == 0 {
			_, err = fmt.Fprintln(f.Out, "no changes")
		} else {
			_, err = fmt.Fprintf(f.Out, "%d changes planned; rerun with --apply to make them\n", f.planned)
		}
		return err
	}
	plan["resource_ids"] = ids
	if err := f.Check(plan); err != nil {
		return fmt.Errorf("the bound foundation fails inspection: %w", err)
	}
	return write(out, plan, f.Out)
}

func write(out string, plan Object, log io.Writer) error {
	wire, err := json.Marshal(plan, json.Deterministic(true), jsontext.Multiline(true), json.FormatNilMapAsNull(true))
	if err != nil {
		return err
	}
	wire = append(wire, '\n')
	if old, err := os.ReadFile(out); err == nil {
		if !bytes.Equal(old, wire) {
			return fmt.Errorf("%s exists and differs from the bound plan; it is never overwritten", out)
		}
		_, err = fmt.Fprintln(log, "unchanged: "+out)
		return err
	} else if !errors.Is(err, os.ErrNotExist) {
		return err
	}
	if err := os.WriteFile(out+".tmp", wire, 0o644); err != nil {
		return err
	}
	if err := os.Rename(out+".tmp", out); err != nil {
		return err
	}
	_, err = fmt.Fprintln(log, "wrote: "+out)
	return err
}

func (f *Foundation) call(ctx context.Context, c command.Client, args ...string) (any, error) {
	var release func()
	mutation := false
	for _, arg := range args {
		if strings.HasPrefix(arg, "--") {
			break
		}
		mutation = mutation || slices.Contains([]string{"create", "add", "remove", "update", "connect"}, arg)
	}
	if mutation {
		if f.BeforeWrite == nil || f.Guard == nil {
			return nil, errors.New("foundation mutation requires durable authority and a retry guard")
		}
		var err error
		ctx, release, err = f.BeforeWrite(ctx, len(args) > 0 && args[0] == "iam")
		if err != nil {
			return nil, fmt.Errorf("foundation write authority: %w", err)
		}
		if ctx == nil || release == nil {
			if release != nil {
				release()
			}
			return nil, errors.New("foundation authority returned no lease release")
		}
		defer release()
		if err := ctx.Err(); err != nil {
			return nil, err
		}
		if f.Guard != nil {
			if err := f.Guard(ctx); err != nil {
				return nil, err
			}
			ctx = ociclient.WithAuthority(ctx, f.Guard)
		}
	}
	r, err := c.Call(ctx, args...)
	if err != nil {
		return nil, err
	}
	return r["data"], nil
}

func (f *Foundation) data(ctx context.Context, c command.Client, args ...string) (Object, error) {
	v, err := f.call(ctx, c, args...)
	if err != nil {
		return nil, err
	}
	return command.Object(v)
}

// find returns the one live row of a list whose field is name. A list scoped
// by a parent a dry run has not created yet finds nothing.
func (f *Foundation) find(c command.Client, field, name string, args ...string) func(context.Context) (Object, error) {
	return func(ctx context.Context) (Object, error) {
		if slices.Contains(args, "") {
			return nil, nil
		}
		v, err := f.call(ctx, c, args...)
		if err != nil {
			return nil, err
		}
		rows, err := command.Rows(v)
		if err != nil {
			return nil, err
		}
		var found Object
		for _, r := range rows {
			if r[field] == name && !slices.Contains([]string{"TERMINATED", "TERMINATING", "DELETED", "DELETING", "PENDING_DELETION", "SCHEDULING_DELETION"}, fmt.Sprint(r["lifecycle-state"])) {
				if found != nil {
					return nil, fmt.Errorf("more than one live resource is named %s", name)
				}
				found = r
			}
		}
		return f.verifyFound(name, found)
	}
}

func (f *Foundation) verifyFound(name string, found Object) (Object, error) {
	if expected := f.expected[name]; expected != "" && (found == nil || found["id"] != expected) {
		return nil, fmt.Errorf("recorded resource %s (%s) is missing or differs; refusing replacement", name, expected)
	}
	if found != nil && len(f.ownership) > 0 && f.expected[name] == "" {
		return nil, &unrecordedResource{name: name, id: text(found["id"])}
	}
	return found, nil
}

func (f *Foundation) create(c command.Client, args ...string) func(context.Context) (Object, error) {
	return func(ctx context.Context) (Object, error) {
		words := slices.Clone(args)
		if len(f.ownership) > 0 {
			words = append(words, "--freeform-tags", command.JSON(f.ownership))
		}
		if f.PrepareCreate != nil {
			parsed, err := sdkcli.Parse(words)
			if err != nil {
				return nil, err
			}
			name := parsed.Flags["display-name"]
			if name == "" {
				name = parsed.Flags["name"]
			}
			region := f.region
			if sdk, ok := c.(*publicapi.SDKClient); ok {
				region = sdk.Region
			}
			digest, token, err := publicapi.CreateRetryIdentity(ctx, region, words...)
			if err != nil {
				return nil, err
			}
			identity := CreateIdentity{Key: f.resourceKeys[name], Region: region, RequestDigest: digest, RetryToken: token}
			if err := identity.Validate(); err != nil {
				return nil, err
			}
			if recoveringCreate(ctx) && token == "" {
				return nil, errors.New("OCI create has no retry token; unknown result requires exact provider observation")
			}
			if err := f.PrepareCreate(ctx, identity, recoveringCreate(ctx)); err != nil {
				return nil, fmt.Errorf("prepare durable OCI create: %w", err)
			}
		}
		return f.data(ctx, c, words...)
	}
}

// ensure finds a resource or, with Apply, creates it. A dry run reports the
// create and returns nil. A found resource valid rejects is refused.
func (f *Foundation) ensure(ctx context.Context, what string, find, create func(context.Context) (Object, error), valid func(Object) bool) (Object, error) {
	r, err := find(ctx)
	if err != nil {
		unknown, recoverable := errors.AsType[*unrecordedResource](err)
		if !recoverable || !f.Apply || f.PrepareCreate == nil || unknown.id == "" {
			return nil, fmt.Errorf("find %s: %w", what, err)
		}
		r, err = create(context.WithValue(ctx, recoveringCreateKey{}, true))
		if err != nil {
			return nil, fmt.Errorf("recover %s: %w", what, errors.Join(unknown, err))
		}
		if text(r["id"]) != unknown.id {
			return nil, fmt.Errorf("recovered %s differs from observed resource identity", what)
		}
	}
	if r == nil {
		if !f.Apply {
			f.planned++
			_, err := fmt.Fprintln(f.Out, "plan: create "+what)
			return nil, err
		}
		if r, err = create(ctx); err != nil {
			return nil, fmt.Errorf("create %s: %w", what, err)
		}
		fmt.Fprintln(f.Out, "created: "+what)
	}
	if !valid(r) {
		return nil, fmt.Errorf("%s exists but differs from the plan; inspect it before rerunning", what)
	}
	return r, nil
}

func (f *Foundation) await(ctx context.Context, c command.Client, what, state string, tolerate bool, args ...string) (Object, error) {
	attempts := f.PollAttempts
	if attempts <= 0 {
		attempts = 60
	}
	pause := f.Pause
	if pause == nil {
		pause = command.Pause
	}
	for n := 1; ; n++ {
		r, err := f.data(ctx, c, args...)
		if err == nil && r["lifecycle-state"] == state {
			return r, nil
		}
		if err != nil && (!tolerate || n == attempts) {
			return nil, fmt.Errorf("read %s: %w", what, err)
		}
		if n == attempts {
			return nil, fmt.Errorf("%s did not become %s", what, state)
		}
		if err := pause(ctx, 10*time.Second); err != nil {
			return nil, err
		}
	}

func (f *Foundation) bind(ctx context.Context, plan Object) (Object, error) {
	region := text(plan["region"])
	entry, _ := catalog.CellForOCIRegion(region)
	sec, secret := obj(plan["network_security"]), obj(plan["host_credential_secret"])
	service := text(sec["service_gateway_service_id"])
	switch {
	case plan["operator_gateway"] != nil:
		return nil, errors.New("foundation does not create an operator gateway peering; plan operator_gateway must be null")
	case secret["compartment_id"] != nil || secret["secret_id"] != nil:
		return nil, errors.New("foundation creates no host LiveS3Credential policy; plan host_credential_secret must be null")
	case service == "" || sec["service_gateway_cidr_block"] != "all-"+strings.ToLower(entry.OCIRegionKey)+"-services-in-oracle-services-network":
		return nil, fmt.Errorf("plan service gateway must route all %s services in the Oracle Services Network", entry.OCIRegionKey)
	}
	cell, err := naming.RegionCell(entry.Cell).Name()
	if err != nil {
		return nil, err
	}
	description := "TerraScale " + cell + " foundation (ts-orch oci-region foundation)"
	ids := maps.Clone(obj(plan["resource_ids"]))
	if ids == nil {
		ids = Object{}
	}
	f.ownership = map[string]string{"terrascale.owner": "ts-orch", "terrascale.cell": cell}
	if f.OperationID != "" {
		f.ownership["terrascale.operation"] = f.OperationID
	}
	f.expected = map[string]string{}
	f.resourceKeys = map[string]string{}
	remember := func(name, key, expected string) {
		f.expected[name], f.resourceKeys[name] = expected, key
	}
	names := obj(plan["preview_compartment_names"])
	for _, role := range []string{"control", "network", "workload"} {
		remember(text(names[role]), role+"_compartment", text(ids[role+"_compartment"]))
	}
	for key, suffix := range map[string]string{"vault": "vault", "key": "key", "vcn": "vcn", "service_gateway": "service-gateway", "route_table": "private-routes", "security_list": "private-security", "subnet": "private", "network_security_group": "controllers-nsg", "workload_network_security_group": "databases-nsg"} {
		remember(cell+"-"+suffix, key, text(ids[key]))
	}
	identity := obj(plan["identity"])
	for key, field := range map[string]string{"controller_dynamic_group": "controller_dynamic_group_name", "host_dynamic_group": "host_dynamic_group_name", "controller_policy": "controller_policy_name", "objectstorage_key_policy": "objectstorage_key_policy_name"} {
		remember(text(identity[field]), key, text(ids[key]))
	}
	for key, name := range map[string]string{"controller_usage_policy": cell + "-controller-usage", "netbird_enrollment_policy": cell + "-netbird-enrollment"} {
		remember(name, key, f.AuxiliaryIDs[key])
	}
	for _, role := range []string{"ledger", "head", "backup", "material"} {
		key := role + "_bucket"
		remember(text(obj(plan["foundation_buckets"])[role]), key, f.AuxiliaryIDs[key])
	}
	bind := func(key string, r Object) error {
		if r == nil {
			return nil
		}
		if old := text(ids[key]); old != "" && old != r["id"] {
			return fmt.Errorf("plan binds %s %s, but its live resource is %v", key, old, r["id"])
		}
		resourceID, err := command.ID(r)
		if err != nil {
			return err
		}
		if f.Apply {
			if f.Checkpoint == nil {
				return errors.New("foundation binding requires durable checkpoints")
			}
			if err := f.Checkpoint(ctx, key, resourceID); err != nil {
				return fmt.Errorf("checkpoint %s: %w", key, err)
			}
		}
		ids[key] = resourceID
		return nil
	}
	id := func(key string) string { return text(ids[key]) }
	parent, tenancy := text(plan["parent_compartment_id"]), text(plan["tenancy_id"])

	for _, role := range []string{"control", "network", "workload"} {
		name := text(names[role])
		what := "compartment " + name
		r, err := f.ensure(ctx, what, f.find(f.Home, "name", name, "iam", "compartment", "list", "--compartment-id", parent, "--all"),
			f.create(f.Home, "iam", "compartment", "create", "--compartment-id", parent, "--name", name, "--description", description),
			func(r Object) bool { return r["compartment-id"] == parent })
		if err != nil {
			return nil, err
		}
		if r != nil {
			get := []string{"iam", "compartment", "get", "--compartment-id", text(r["id"])}
			if _, err := f.await(ctx, f.Home, what, "ACTIVE", false, get...); err != nil {
				return nil, err
			}
			if _, err := f.await(ctx, f.Region, what+" in "+region, "ACTIVE", true, get...); err != nil {
				return nil, err
			}
		}
		if err := bind(role+"_compartment", r); err != nil {
			return nil, err
		}
	}
	network, control := id("network_compartment"), id("control_compartment")

	if err := f.network(ctx, plan, cell, network, bind, id); err != nil {
		return nil, err
	}

	vault, err := f.ensure(ctx, "Vault "+cell+"-vault", f.find(f.Region, "display-name", cell+"-vault", "kms", "management", "vault", "list", "--compartment-id", control, "--all"),
		f.create(f.Region, "kms", "management", "vault", "create", "--compartment-id", control, "--display-name", cell+"-vault", "--vault-type", "DEFAULT"),
		func(r Object) bool { return r["vault-type"] == "DEFAULT" && r["compartment-id"] == control })
	if err != nil {
		return nil, err
	}
	endpoint := ""
	if vault != nil {
		if vault, err = f.await(ctx, f.Region, "Vault "+cell+"-vault", "ACTIVE", false, "kms", "management", "vault", "get", "--vault-id", text(vault["id"])); err != nil {
			return nil, err
		}
		endpoint = text(vault["management-endpoint"])
	}
	if err := bind("vault", vault); err != nil {
		return nil, err
	}
	key, err := f.ensure(ctx, "HSM key "+cell+"-key", f.find(f.Region, "display-name", cell+"-key", "kms", "management", "key", "list", "--compartment-id", control, "--endpoint", endpoint, "--all"),
		f.create(f.Region, "kms", "management", "key", "create", "--compartment-id", control, "--display-name", cell+"-key",
			"--key-shape", `{"algorithm":"AES","length":32}`, "--protection-mode", "HSM", "--endpoint", endpoint),
		func(r Object) bool {
			return r["compartment-id"] == control && r["protection-mode"] == "HSM" && r["vault-id"] == id("vault")
		})
	if err != nil {
		return nil, err
	}
	if key != nil {
		if _, err := f.await(ctx, f.Region, "HSM key "+cell+"-key", "ENABLED", false, "kms", "management", "key", "get", "--key-id", text(key["id"]), "--endpoint", endpoint); err != nil {
			return nil, err
		}
	}
	if err := bind("key", key); err != nil {
		return nil, err
	}

	if err := f.iam(ctx, plan, ids, cell, description, tenancy, parent, bind); err != nil {
		return nil, err
	}
	return ids, f.buckets(ctx, plan, control, id("key"))
}

func (f *Foundation) network(ctx context.Context, plan Object, cell, network string, bind func(string, Object) error, id func(string) string) error {
	sec := obj(plan["network_security"])
	inVCN := func(r Object) bool { return r["compartment-id"] == network && r["vcn-id"] == id("vcn") }
	list := func(kind, name string) func(context.Context) (Object, error) {
		return f.find(f.Region, "display-name", name, "network", kind, "list", "--compartment-id", network, "--vcn-id", id("vcn"), "--all")
	}
	create := func(kind, name string, args ...string) func(context.Context) (Object, error) {
		return f.create(f.Region, append([]string{"network", kind, "create", "--compartment-id", network, "--vcn-id", id("vcn"), "--display-name", name, "--wait-for-state", "AVAILABLE"}, args...)...)
	}
	vcn, err := f.ensure(ctx, "VCN "+cell+"-vcn", f.find(f.Region, "display-name", cell+"-vcn", "network", "vcn", "list", "--compartment-id", network, "--all"),
		f.create(f.Region, "network", "vcn", "create", "--compartment-id", network, "--display-name", cell+"-vcn", "--cidr-block", text(plan["network_cidr"]),
			"--dns-label", strings.ReplaceAll(cell, "-", ""), "--wait-for-state", "AVAILABLE"),
		func(r Object) bool { return r["compartment-id"] == network && r["cidr-block"] == plan["network_cidr"] })
	if err != nil {
		return err
	}
	if err := bind("vcn", vcn); err != nil {
		return err
	}

	service := text(sec["service_gateway_service_id"])
	gateway, err := f.ensure(ctx, "service gateway "+cell+"-service-gateway", list("service-gateway", cell+"-service-gateway"),
		create("service-gateway", cell+"-service-gateway", "--services", command.JSON([]any{Object{"serviceId": service}})),
		func(r Object) bool {
			services, _ := command.Rows(r["services"])
			return inVCN(r) && len(services) == 1 && services[0]["service-id"] == service
		})
	if err != nil {
		return err
	}
	if err := bind("service_gateway", gateway); err != nil {
		return err
	}

	routes, err := f.ensure(ctx, "route table "+cell+"-private-routes", list("route-table", cell+"-private-routes"),
		create("route-table", cell+"-private-routes", "--route-rules", command.JSON([]any{Object{"destination": sec["service_gateway_cidr_block"],
			"destinationType": "SERVICE_CIDR_BLOCK", "networkEntityId": id("service_gateway")}})), inVCN)
	if err != nil {
		return err
	}
	if err := bind("route_table", routes); err != nil {
		return err
	}

	security, err := f.ensure(ctx, "security list "+cell+"-private-security", list("security-list", cell+"-private-security"),
		create("security-list", cell+"-private-security", "--ingress-security-rules", command.JSON(rules(sec["security_list_ingress_rules"], false)),
			"--egress-security-rules", command.JSON(rules(sec["security_list_egress_rules"], false))), inVCN)
	if err != nil {
		return err
	}
	if err := bind("security_list", security); err != nil {
		return err
	}

	subnet, err := f.ensure(ctx, "subnet "+cell+"-private", list("subnet", cell+"-private"),
		create("subnet", cell+"-private", "--cidr-block", text(plan["subnet_cidr"]), "--dns-label", "private", "--prohibit-public-ip-on-vnic", "true",
			"--route-table-id", id("route_table"), "--security-list-ids", command.JSON([]string{id("security_list")})),
		func(r Object) bool {
			return inVCN(r) && r["cidr-block"] == plan["subnet_cidr"] && r["prohibit-public-ip-on-vnic"] == true
		})
	if err != nil {
		return err
	}
	if err := bind("subnet", subnet); err != nil {
		return err
	}

	for _, n := range []struct{ key, rules, name string }{{"network_security_group", "nsg_rules", cell + "-controllers-nsg"},
		{"workload_network_security_group", "workload_nsg_rules", cell + "-databases-nsg"}} {
		if len(arr(sec[n.rules])) == 0 && n.key == "workload_network_security_group" {
			continue
		}
		nsg, err := f.ensure(ctx, "NSG "+n.name, list("nsg", n.name), create("nsg", n.name), inVCN)
		if err != nil {
			return err
		}
		if err := bind(n.key, nsg); err != nil {
			return err
		}
		// Rules are added in one call, so an NSG has none or all of them;
		// inspection compares them with the plan.
		var live []Object
		if nsg != nil {
			v, err := f.call(ctx, f.Region, "network", "nsg", "rules", "list", "--nsg-id", text(nsg["id"]), "--all")
			if err == nil {
				live, err = command.Rows(v)
			}
			if err != nil {
				return fmt.Errorf("read NSG %s rules: %w", n.name, err)
			}
		}
		if len(live) > 0 {
			continue
		}
		what := fmt.Sprintf("%d rules on NSG %s", len(arr(sec[n.rules])), n.name)
		if !f.Apply {
			f.planned++
			fmt.Fprintln(f.Out, "plan: add "+what)
			continue
		}
		if _, err := f.call(ctx, f.Region, "network", "nsg", "rules", "add", "--nsg-id", text(nsg["id"]), "--security-rules", command.JSON(rules(sec[n.rules], true))); err != nil {
			return fmt.Errorf("add %s: %w", what, err)
		}
		fmt.Fprintln(f.Out, "added: "+what)
	}
	return nil
}

func (f *Foundation) iam(ctx context.Context, plan, ids Object, cell, description, tenancy, parent string, bind func(string, Object) error) error {
	identity := obj(plan["identity"])
	for _, g := range []struct{ key, name, compartment string }{{"controller_dynamic_group", "controller_dynamic_group_name", "control_compartment"},
		{"host_dynamic_group", "host_dynamic_group_name", "workload_compartment"}} {
		name := text(identity[g.name])
		rule := fmt.Sprintf("ALL {instance.compartment.id = '%s'}", text(ids[g.compartment]))
		r, err := f.ensure(ctx, "dynamic group "+name, f.find(f.Home, "name", name, "iam", "dynamic-group", "list", "--compartment-id", tenancy, "--all"),
			f.create(f.Home, "iam", "dynamic-group", "create", "--compartment-id", tenancy, "--name", name, "--description", description, "--matching-rule", rule),
			func(r Object) bool { return r["compartment-id"] == tenancy && r["matching-rule"] == rule })
		if err != nil {
			return err
		}
		if err := bind(g.key, r); err != nil {
			return err
		}
	}
	controller, err := ociregion.RequiredStorageControllerStatements(plan, ids, text(plan["bootstrap_object_prefix"]), f.HomeStorageDomain)
	if err != nil {
		return err
	}
	storageKeys, err := ociregion.ObjectStorageKeyStatements(plan, ids, f.HomeStorageDomain)
	if err != nil {
		return err
	}
	type policy struct {
		key, name, compartment string
		statements             []string
	}
	control := text(ids["control_compartment"])
	policies := []policy{{"objectstorage_key_policy", text(identity["objectstorage_key_policy_name"]), control, storageKeys},
		{"controller_policy", text(identity["controller_policy_name"]), parent, controller},
		// Usage API statements must name the tenancy, so this one sits in
		// the root compartment; the controller policy's parent is not it.
		{"controller_usage_policy", cell + "-controller-usage", tenancy, []string{fmt.Sprintf("Allow dynamic-group %s to read usage-report in tenancy", text(identity["controller_dynamic_group_name"]))}}}
	if plan["netbird"] == nil {
		// Without a plan-bound NetBird secret, both dynamic groups may read
		// the setup key by its static name once it is stored. No resource ID
		// records this policy and inspect-foundation does not read it.
		var statements []string
		for _, g := range []string{"controller_dynamic_group_name", "host_dynamic_group_name"} {
			statements = append(statements, fmt.Sprintf("Allow dynamic-group %s to read secret-bundles in compartment id %s where target.secret.name = '%s-netbird-setup-key'", text(identity[g]), control, cell))
		}
		policies = append(policies, policy{"netbird_enrollment_policy", cell + "-netbird-enrollment", control, statements})
	}
	for _, p := range policies {
		name := p.name
		r, err := f.ensure(ctx, "policy "+name, f.find(f.Home, "name", name, "iam", "policy", "list", "--compartment-id", p.compartment, "--all"),
			f.create(f.Home, "iam", "policy", "create", "--compartment-id", p.compartment, "--name", name, "--description", description, "--statements", command.JSON(p.statements)),
			func(r Object) bool {
				return r["compartment-id"] == p.compartment && command.JSON(r["statements"]) == command.JSON(p.statements)
			})
		if err != nil {
			return err
		}
		if p.key == "controller_usage_policy" || p.key == "netbird_enrollment_policy" {
			if err := f.bindAuxiliary(ctx, p.key, r); err != nil {
				return err
			}
			continue
		}
		if err := bind(p.key, r); err != nil {
			return err
		}
	}
	return nil
}

func (f *Foundation) buckets(ctx context.Context, plan Object, control, key string) error {
	namespace := ""
	if f.Apply || control != "" {
		v, err := f.call(ctx, f.Region, "os", "ns", "get")
		if err != nil {
			return fmt.Errorf("read the Object Storage namespace: %w", err)
		}
		namespace = text(v)
		if f.HomeStorageDomain != (bootstrap.StorageDomain{}) && namespace != f.HomeStorageDomain.Namespace {
			return errors.New("live namespace differs from signed home storage")
		}
	}
	names := obj(plan["foundation_buckets"])
	for _, role := range []string{"ledger", "head", "backup", "material"} {
		bucketKey, err := ociregion.FoundationBucketKey(plan, Object{"key": key}, role, f.HomeStorageDomain)
		if err != nil {
			return err
		}
		name := text(names[role])
		versioning := "Disabled"
		if role == "head" || role == "material" {
			versioning = "Enabled"
		}
		bucket, err := f.ensure(ctx, "bucket "+name, func(ctx context.Context) (Object, error) {
			if control == "" {
				return nil, nil
			}
			v, err := f.call(ctx, f.Region, "os", "bucket", "list", "--compartment-id", control, "--all")
			if err != nil {
				return nil, err
			}
			rows, err := command.Rows(v)
			if err != nil {
				return nil, err
			}
			var found Object
			for _, row := range rows {
				if row["name"] != name {
					continue
				}
				if found != nil {
					return nil, fmt.Errorf("more than one live bucket is named %s", name)
				}
				// A summary omits the bucket OCID, encryption and versioning.
				found, err = f.data(ctx, f.Region, "os", "bucket", "get", "--namespace-name", namespace, "--bucket-name", name)
				if err != nil {
					return nil, err
				}
			}
			return f.verifyFound(name, found)
		}, f.create(f.Region, "os", "bucket", "create", "--namespace-name", namespace, "--compartment-id", control, "--name", name, "--kms-key-id", bucketKey,
			"--versioning", versioning, "--public-access-type", "NoPublicAccess", "--storage-tier", "Standard"),
			func(r Object) bool {
				return r["compartment-id"] == control && r["public-access-type"] == "NoPublicAccess" && r["kms-key-id"] == bucketKey && r["versioning"] == versioning
			})
		if err != nil {
			return err
		}
		if err := f.bindAuxiliary(ctx, role+"_bucket", bucket); err != nil {
			return err
		}
		if versioning == "Enabled" {
			continue
		}
		what := "retention rule " + role + "-retention on bucket " + name
		if bucket != nil {
			v, err := f.call(ctx, f.Region, "os", "retention-rule", "list", "--namespace-name", namespace, "--bucket-name", name, "--all")
			if err != nil {
				return fmt.Errorf("read %s: %w", what, err)
			}
			if len(arr(v)) > 0 {
				continue
			}
		}
		if !f.Apply {
			f.planned++
			fmt.Fprintln(f.Out, "plan: create "+what)
			continue
		}
		if _, err := f.call(ctx, f.Region, "os", "retention-rule", "create", "--namespace-name", namespace, "--bucket-name", name,
			"--display-name", role+"-retention", "--time-amount", fmt.Sprint(plan["bucket_retention_days"]), "--time-unit", "DAYS"); err != nil {
			return fmt.Errorf("create %s: %w", what, err)
		}
		fmt.Fprintln(f.Out, "created: "+what)
	}
	return nil
}

func (f *Foundation) bindAuxiliary(ctx context.Context, key string, resource Object) error {
	if resource == nil {
		return nil
	}
	id, err := command.ID(resource)
	if err != nil {
		return err
	}
	if old := f.AuxiliaryIDs[key]; old != "" && old != id {
		return errors.New("auxiliary foundation identity cannot be replaced")
	}
	if f.Apply {
		if f.CheckpointAuxiliary == nil {
			return errors.New("auxiliary foundation identity requires a durable checkpoint")
		}
		if err := f.CheckpointAuxiliary(ctx, key, id); err != nil {
			return err
		}
	}
	return nil

func FoundationBucketKey(plan, ids Object, role string, home bootstrap.StorageDomain) (string, error) {
	return capture(func() string {
		key := text(ids["key"])
		if home == (bootstrap.StorageDomain{}) {
			return key
		}
		names := obj(plan["foundation_buckets"])
		if home.Validate() != nil || plan["cell"] != "GRU" || plan["region"] != "sa-saopaulo-1" ||
			names["ledger"] != home.LedgerBucket || names["head"] != home.HeadBucket || key != home.HeadKMSKeyOCID {
			fail("signed home storage differs from the GRU foundation plan")
		}
		requireOCID(home.LedgerKMSKeyOCID, "key", "sa-saopaulo-1")
		requireOCID(home.HeadKMSKeyOCID, "key", "sa-saopaulo-1")
		if role == "ledger" {
			return home.LedgerKMSKeyOCID
		}
		return key
	})
}

// RequiredStorageControllerStatements includes the exact signed home ledger
// key when it differs from the plan's head/material key.
func RequiredStorageControllerStatements(plan, ids Object, prefix string, home bootstrap.StorageDomain) ([]string, error) {
	ledger, err := FoundationBucketKey(plan, ids, "ledger", home)
	if err != nil {
		return nil, err
	}
	return capture(func() []string { return controllerStatements(plan, ids, prefix, ledger) })
}

// ObjectStorageKeyStatements grants the regional service only the distinct
// keys used by the plan and its independently verified home storage domain.
func ObjectStorageKeyStatements(plan, ids Object, home bootstrap.StorageDomain) ([]string, error) {
	ledger, err := FoundationBucketKey(plan, ids, "ledger", home)
	if err != nil {
		return nil, err
	}
	return capture(func() []string {
		statements := []string{ObjectStorageKeyStatement(plan, ids)}
		if ledger != text(ids["key"]) {
			statements = append(statements, ObjectStorageKeyStatement(plan, Object{"key": ledger}))
		}
		return statements
	})

func (e *Engine) liveNetbirdIAM(plan Object) {
	if plan["netbird"] == nil {
		return
	}
	requireNetbirdIDs(plan)
	c := obj(plan["netbird"])
	policy := requireLiveID(e.oci("", "iam", "policy", "get", "--policy-id", str(c["policy_id"])), c["policy_id"], "NetBird server enrollment IAM policy")
	if policy["lifecycle-state"] != "ACTIVE" || policy["name"] != c["policy_name"] || policy["compartment-id"] != c["secret_compartment_id"] || !eq(policy["statements"], netbirdStatements(plan)) {
		fail("live NetBird server enrollment policy differs from exact secret read grants")
	}
	secret := requireLiveID(e.oci(text(plan["region"]), "vault", "secret", "get", "--secret-id", str(c["setup_key_secret_id"])), c["setup_key_secret_id"], "NetBird setup-key secret")
	if secret["lifecycle-state"] != "ACTIVE" || secret["compartment-id"] != c["secret_compartment_id"] {
		fail("live NetBird setup-key secret is not active in its selected compartment")
	}
}
func (e *Engine) liveIAM(plan, ids Object, prefix string) {
	identity := obj(plan["identity"])
	bound := liveS3Bound(plan, ids)
	group := requireLiveID(e.oci("", "iam", "dynamic-group", "get", "--dynamic-group-id", str(ids["controller_dynamic_group"])), ids["controller_dynamic_group"], "controller dynamic group")
	if group["lifecycle-state"] != "ACTIVE" || group["name"] != identity["controller_dynamic_group_name"] || group["matching-rule"] != fmt.Sprintf("ALL {instance.compartment.id = '%s'}", str(ids["control_compartment"])) {
		fail("live controller dynamic group does not exactly isolate controller instances")
	}
	policy := requireLiveID(e.oci("", "iam", "policy", "get", "--policy-id", str(ids["controller_policy"])), ids["controller_policy"], "controller IAM policy")
	if policy["lifecycle-state"] != "ACTIVE" || policy["name"] != identity["controller_policy_name"] || policy["compartment-id"] != plan["parent_compartment_id"] || !eq(policy["statements"], must(RequiredStorageControllerStatements(plan, ids, prefix, e.HomeStorageDomain))) {
		fail("live controller IAM policy differs from exact reviewed statements")
	}
	kp := requireLiveID(e.oci("", "iam", "policy", "get", "--policy-id", str(ids["objectstorage_key_policy"])), ids["objectstorage_key_policy"], "Object Storage key IAM policy")
	if kp["lifecycle-state"] != "ACTIVE" || kp["name"] != identity["objectstorage_key_policy_name"] || kp["compartment-id"] != ids["control_compartment"] {
		fail("live Object Storage key policy differs from exact reviewed statements")
	}
	statements := must(ObjectStorageKeyStatements(plan, ids, e.HomeStorageDomain))
	if !eq(kp["statements"], statements) {
		fail("Object Storage key policy is not limited to the reviewed region and key")
	}
	hg := requireLiveID(e.oci("", "iam", "dynamic-group", "get", "--dynamic-group-id", str(ids["host_dynamic_group"])), ids["host_dynamic_group"], "workload host dynamic group")
	if hg["lifecycle-state"] != "ACTIVE" || hg["name"] != identity["host_dynamic_group_name"] || hg["matching-rule"] != fmt.Sprintf("ALL {instance.compartment.id = '%s'}", str(ids["workload_compartment"])) {
		fail("live workload host dynamic group does not exactly isolate workload instances")
	}
	if !bound {
		e.call("check_live_netbird_iam", []any{plan}, Object{})
		return
	}
	secretConfig := obj(plan["host_credential_secret"])
	compartment, secretID := secretConfig["compartment_id"], secretConfig["secret_id"]
	hp := requireLiveID(e.oci("", "iam", "policy", "get", "--policy-id", str(ids["host_policy"])), ids["host_policy"], "host LiveS3Credential IAM policy")
	statement := fmt.Sprintf("Allow dynamic-group %s to read secret-bundles in compartment id %s where target.secret.id = '%s'", str(identity["host_dynamic_group_name"]), str(compartment), str(secretID))
	if hp["lifecycle-state"] != "ACTIVE" || hp["name"] != identity["host_policy_name"] || hp["compartment-id"] != compartment || !eq(hp["statements"], []string{statement}) {
		fail("host LiveS3Credential policy is not limited to the selected secret and compartment")
	}
	secret := requireLiveID(e.oci(text(plan["region"]), "vault", "secret", "get", "--secret-id", str(secretID)), secretID, "host LiveS3Credential secret")
	if secret["lifecycle-state"] != "ACTIVE" || secret["compartment-id"] != compartment {
		fail("live host LiveS3Credential secret is not active in its selected compartment")
	}
	e.call("check_live_netbird_iam", []any{plan}, Object{})
}

	vault := requireLiveID(e.oci(text(plan["region"]), "kms", "management", "vault", "get", "--vault-id", str(ids["vault"])), ids["vault"], "Vault")
	if vault["lifecycle-state"] != "ACTIVE" || vault["vault-type"] != "DEFAULT" || vault["compartment-id"] != ids["control_compartment"] {
		fail("live Vault is not active in the plan control compartment")
	}
	endpoint := text(vault["management-endpoint"])
	if !strings.HasPrefix(endpoint, "https://") || len(endpoint) > 512 {
		fail("live Vault management endpoint is invalid")
	}
	key := requireLiveID(e.oci(text(plan["region"]), "kms", "management", "key", "get", "--key-id", str(ids["key"]), "--endpoint", endpoint), ids["key"], "KMS key")
	state := key["lifecycle-state"]
	if state == nil {
		state = key["key-state"]
	}
	shape := obj(key["key-shape"])
	if state != "ENABLED" || key["compartment-id"] != ids["control_compartment"] || key["vault-id"] != ids["vault"] || key["protection-mode"] != "HSM" || shape["algorithm"] != "AES" || !eq(shape["length"], 32) {
		fail("live KMS key state or cryptographic shape differs from the plan")
	}
}
func (e *Engine) liveBuckets(plan, ids Object) string {
	namespace := str(e.oci(text(plan["region"]), "os", "ns", "get"))
	if e.HomeStorageDomain != (bootstrap.StorageDomain{}) && namespace != e.HomeStorageDomain.Namespace {
		fail("live namespace differs from signed home storage")
	}
	names := obj(plan["foundation_buckets"])
	for _, role := range []string{"ledger", "head", "backup", "material"} {
		key := must(FoundationBucketKey(plan, ids, role, e.HomeStorageDomain))
		name := str(names[role])
		bucket := obj(e.oci(text(plan["region"]), "os", "bucket", "get", "--namespace-name", namespace, "--bucket-name", name))
		versioning, retentionName := "Disabled", ""
		if role == "head" || role == "material" {
			versioning = "Enabled"
		} else {
			retentionName = role + "-retention"
		}
		if bucket["name"] != name || bucket["compartment-id"] != ids["control_compartment"] || bucket["public-access-type"] != "NoPublicAccess" || bucket["storage-tier"] != "Standard" || bucket["versioning"] != versioning || bucket["kms-key-id"] != key {
			fail("live " + role + " bucket privacy, KMS, tier, compartment, or versioning differs from the plan")
		}
		retention := rows(e.oci(text(plan["region"]), "os", "retention-rule", "list", "--namespace-name", namespace, "--bucket-name", name, "--all"))
		if retentionName == "" {
			if len(retention) > 0 {
				fail("live " + role + " bucket has an unplanned retention rule")
			}
		} else if len(retention) != 1 || obj(retention[0])["display-name"] != retentionName {
			fail("live " + role + " bucket retention differs from the exact plan")
		} else {
			duration := obj(obj(retention[0])["duration"])
			if duration["time-amount"] == nil {
				fail("live " + role + " bucket retention duration is invalid")
			}
			if duration["time-unit"] != "DAYS" || !eq(number(duration["time-amount"]), number(plan["bucket_retention_days"])) {
				fail("live " + role + " bucket retention differs from the exact plan")
			}
		}
	}
	return namespace

// DecodeCreate checks a create command as its in-binary creator reads it,
// without calling OCI: the creator consumes every flag and each JSON flag
// decodes into its SDK type. The foundation's tests check its commands with
// it.
func DecodeCreate(args []string) error {
	command, err := sdkcli.Parse(args)
	if err != nil {
		return err
	}
	if _, ok := creators[command.Path]; !ok {
		return fmt.Errorf("%w: %s", sdkcli.ErrUnsupported, command.Path)
	}
	if extra := unacceptedCreateFlags(command); len(extra) > 0 {
		return fmt.Errorf("%s sends flags its creator does not consume: %v", command.Path, extra)
	}
	targets := map[string]any{}
	switch command.Path {
	case "iam policy create":
		targets["statements"] = &[]string{}
	case "network service-gateway create":
		targets["services"] = &[]core.ServiceIdRequestDetails{}
	case "kms management key create":
		targets["key-shape"] = &keymanagement.KeyShape{}
	case "network route-table create":
		targets["route-rules"] = &[]core.RouteRule{}
	case "network security-list create":
		targets["ingress-security-rules"], targets["egress-security-rules"] = &[]core.IngressSecurityRule{}, &[]core.EgressSecurityRule{}
	case "network subnet create":
		targets["security-list-ids"] = &[]string{}
	case "network nsg rules add":
		targets["security-rules"] = &[]core.AddSecurityRuleDetails{}
	case "network drg-route-distribution-statement add":
		targets["statements"] = &[]core.AddDrgRouteDistributionStatementDetails{}
	case "network drg-attachment create":
		targets["network-details"] = &drgNetwork{}
	case "network route-table update":
		targets["route-rules"] = &[]core.RouteRule{}

func (e *Engine) call(name string, args []any, kwargs Object) any {
	if e.Dependency != nil && (name == "oci" || name == "checked_tool" || name == "subprocess.run" || name == "cloudflare_origin_ips" || e.Overrides[name]) {
		v, err := e.Dependency(name, args, kwargs)
		if err != nil {
			panic(err)
		}
		return v
	}
	return e.invoke(name, args, kwargs)
}
func (e *Engine) oci(region string, args ...string) any {
	a := make([]any, len(args))
	for i, x := range args {
		a[i] = x
	}
	kw := Object{}
	if region != "" {
		kw["region"] = region
	}
	return e.call("oci", a, kw)
}
